<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Check, FileText, Upload, Play, Trash2, Layers3, Send, Bot, Clock3, MessageSquareText } from '@lucide/vue'
import { aiApi, documentApi, ticketApi } from '@/api/modules'
import type { AiQuestion, DocumentChunk, DocumentRecord, Ticket, TicketLog } from '@/types/api'
import { useAuthStore } from '@/stores/auth'
import BaseModal from '@/components/BaseModal.vue';import StatusBadge from '@/components/StatusBadge.vue'
const route=useRoute();const router=useRouter();const auth=useAuthStore();const id=Number(route.params.id)
const ticket=ref<Ticket>();const logs=ref<TicketLog[]>([]);const documents=ref<DocumentRecord[]>([]);const questions=ref<AiQuestion[]>([]);const loading=ref(true);const error=ref('');const busy=ref('');const action=ref<'accept'|'resolve'|'close'|''>('');const remark=ref('');const selectedFile=ref<File>();const question=ref('');const selectedDocument=ref<number>();const chunks=ref<DocumentChunk[]>([]);const chunkDocument=ref<DocumentRecord>();
const isOwner=computed(()=>ticket.value?.creatorId===auth.user?.userId);const isAssignee=computed(()=>ticket.value?.assigneeId===auth.user?.userId)
const canUpload=computed(()=>auth.isAdmin||isOwner.value||isAssignee.value)
const availableAction=computed(()=>{if(!ticket.value)return null;if(ticket.value.status==='CREATED'&&(auth.isOps||auth.isAdmin))return 'accept';if(ticket.value.status==='PROCESSING'&&(isAssignee.value||auth.isAdmin))return 'resolve';if(ticket.value.status==='RESOLVED'&&(isOwner.value||auth.isAdmin))return 'close';return null})
const actionLabels={accept:'接收工单',resolve:'标记已解决',close:'确认关闭'}
async function load(){loading.value=true;error.value='';try{[ticket.value,logs.value,documents.value]=await Promise.all([ticketApi.detail(id),ticketApi.logs(id),documentApi.list(id)]);questions.value=(await aiApi.page(id)).records}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function doAction(){if(!action.value)return;busy.value='action';try{ticket.value=await ticketApi.action(id,action.value,remark.value);action.value='';remark.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=''}}
async function upload(){if(!selectedFile.value)return;busy.value='upload';try{await documentApi.upload(id,selectedFile.value);selectedFile.value=undefined;documents.value=await documentApi.list(id)}catch(e){error.value=e instanceof Error?e.message:'上传失败'}finally{busy.value=''}}
async function parse(doc:DocumentRecord){busy.value=`parse-${doc.id}`;try{await documentApi.parse(doc.id);documents.value=await documentApi.list(id)}catch(e){error.value=e instanceof Error?e.message:'解析失败';documents.value=await documentApi.list(id)}finally{busy.value=''}}
async function removeDoc(doc:DocumentRecord){if(!confirm(`确认删除文档“${doc.originalName}”吗？`))return;busy.value=`delete-${doc.id}`;try{await documentApi.remove(doc.id);documents.value=await documentApi.list(id)}catch(e){error.value=e instanceof Error?e.message:'删除失败'}finally{busy.value=''}}
async function showChunks(doc:DocumentRecord){busy.value=`chunk-${doc.id}`;try{chunks.value=await documentApi.chunks(doc.id);chunkDocument.value=doc}catch(e){error.value=e instanceof Error?e.message:'读取切片失败'}finally{busy.value=''}}
async function ask(){if(!question.value.trim())return;busy.value='ask';try{const asked=question.value;const answer=await aiApi.ask(id,{question:asked,documentId:selectedDocument.value,topK:5});question.value='';const saved:AiQuestion={id:answer.questionId,ticketId:id,userId:auth.user?.userId||0,question:asked,answer:answer.answer,modelName:answer.modelName,status:'SUCCESS',costTimeMs:answer.costTimeMs,references:answer.references,createTime:new Date().toISOString()};questions.value=[saved,...questions.value.filter(item=>item.id!==saved.id)]}catch(e){error.value=e instanceof Error?e.message:'提问失败'}finally{busy.value=''}}
onMounted(load)
</script>
<template><div v-if="loading" class="loading-state page-loading">正在加载工单详情…</div><div v-else-if="ticket" class="detail-page"><button class="text-button back-link" @click="router.push('/tickets')"><ArrowLeft :size="17"/>返回工单列表</button><section class="ticket-hero"><div class="ticket-hero-main"><div class="detail-badges"><StatusBadge :value="ticket.priority"/><StatusBadge :value="ticket.status"/></div><span class="ticket-number">{{ticket.ticketNo}}</span><h2>{{ticket.title}}</h2><p>{{ticket.description}}</p></div><div class="ticket-meta"><div><span>创建人</span><strong>#{{ticket.creatorId}}</strong></div><div><span>当前处理人</span><strong>{{ticket.assigneeId?'#'+ticket.assigneeId:'尚未分配'}}</strong></div><div><span>最后更新</span><strong>{{new Date(ticket.updateTime).toLocaleString('zh-CN')}}</strong></div><button v-if="availableAction" class="button primary" @click="action=availableAction"><Check :size="18"/>{{actionLabels[availableAction]}}</button></div></section><div v-if="error" class="inline-error">{{error}}<button @click="error=''">×</button></div><div class="detail-grid"><div class="detail-main"><section class="panel"><header class="panel-header"><div><span class="eyebrow">DOCUMENTS</span><h3>关联文档</h3></div><span class="panel-count">{{documents.length}} 个文件</span></header><div v-if="canUpload" class="upload-strip"><label><Upload :size="19"/><span>{{selectedFile?.name||'选择 PDF、DOCX、TXT 或 Markdown'}}</span><input type="file" accept=".pdf,.docx,.txt,.md,.markdown" @change="e=>selectedFile=(e.target as HTMLInputElement).files?.[0]"/></label><button class="button primary small" :disabled="!selectedFile||busy==='upload'" @click="upload">{{busy==='upload'?'上传中…':'上传'}}</button></div><div v-if="!documents.length" class="empty-state small-empty"><FileText :size="30"/><span>还没有关联文档</span></div><div v-else class="document-list"><article v-for="doc in documents" :key="doc.id"><div class="file-icon">{{doc.fileExtension.toUpperCase()}}</div><div class="file-info"><strong>{{doc.originalName}}</strong><span>{{(doc.fileSize/1024).toFixed(1)}} KB · {{new Date(doc.createTime).toLocaleString('zh-CN')}}</span><p v-if="doc.parseError" class="file-error">{{doc.parseError}}</p></div><StatusBadge :value="doc.parseStatus"/><div class="row-actions"><button v-if="doc.parseStatus!=='PARSING'" class="icon-button" title="解析或重新解析" :disabled="busy===`parse-${doc.id}`" @click="parse(doc)"><Play :size="16"/></button><button v-if="doc.parseStatus==='SUCCESS'" class="icon-button" title="查看切片" @click="showChunks(doc)"><Layers3 :size="16"/></button><button v-if="auth.isAdmin||doc.createBy===auth.user?.userId" class="icon-button danger" title="删除文档" @click="removeDoc(doc)"><Trash2 :size="16"/></button></div></article></div></section><section class="panel ai-panel"><header class="panel-header"><div><span class="eyebrow">DOCUMENT Q&A</span><h3>文档智能问答</h3></div><Bot :size="26"/></header><form class="question-form" @submit.prevent="ask"><select v-model="selectedDocument"><option :value="undefined">检索本工单全部已解析文档</option><option v-for="doc in documents.filter(d=>d.parseStatus==='SUCCESS')" :key="doc.id" :value="doc.id">{{doc.originalName}}</option></select><div><textarea v-model="question" maxlength="2000" rows="3" placeholder="例如：磁盘使用率超过 90% 时应该如何处理？"/><button class="button primary" :disabled="busy==='ask'||!question.trim()"><Send :size="17"/>{{busy==='ask'?'生成中…':'提交问题'}}</button></div></form><div v-if="!questions.length" class="empty-state small-empty"><MessageSquareText :size="30"/><span>解析文档后，可以在这里基于内容提问</span></div><div v-else class="qa-list"><article v-for="qa in questions" :key="qa.id"><div class="qa-question"><span>Q</span><strong>{{qa.question}}</strong><time>{{new Date(qa.createTime).toLocaleString('zh-CN')}}</time></div><div class="qa-answer"><span>A</span><p>{{qa.status==='SUCCESS'?qa.answer:qa.errorMessage}}</p></div><div v-if="qa.references?.length" class="reference-list"><span v-for="ref in qa.references" :key="ref.chunkId">文档 #{{ref.documentId}} · Chunk {{ref.chunkIndex}} · {{ref.relevanceScore.toFixed(1)}}</span></div></article></div></section></div><aside class="detail-aside"><section class="panel timeline-panel"><header class="panel-header"><div><span class="eyebrow">ACTIVITY</span><h3>状态时间线</h3></div><Clock3 :size="21"/></header><ol class="timeline"><li v-for="log in logs" :key="log.id"><i/><div><strong>{{log.operationType}}</strong><span>{{log.fromStatus?`${log.fromStatus} → `:''}}{{log.toStatus}}</span><p v-if="log.remark">{{log.remark}}</p><time>#{{log.operatorId}} · {{new Date(log.createTime).toLocaleString('zh-CN')}}</time></div></li></ol></section></aside></div><BaseModal v-if="action" :title="actionLabels[action]" @close="action=''" ><div class="action-confirm"><p>本操作会推进工单状态且不可回退，请确认业务处理已经完成。</p><label>操作备注<textarea v-model.trim="remark" maxlength="512" rows="5" placeholder="选填：记录处理过程或结果"/></label></div><template #footer><button class="button secondary" @click="action=''">取消</button><button class="button primary" :disabled="busy==='action'" @click="doAction">{{busy==='action'?'提交中…':'确认操作'}}</button></template></BaseModal><BaseModal v-if="chunkDocument" :title="`${chunkDocument.originalName} · 文本切片`" wide @close="chunkDocument=undefined"><div v-if="!chunks.length" class="empty-state">没有切片数据</div><div v-else class="chunk-list"><article v-for="chunk in chunks" :key="chunk.id"><header><strong>Chunk {{chunk.chunkIndex}}</strong><span>{{chunk.tokenCount||0}} tokens<span v-if="chunk.pageNumber"> · 第 {{chunk.pageNumber}} 页</span></span></header><p>{{chunk.content}}</p></article></div></BaseModal></div><div v-else class="empty-state page-loading">工单不存在或无权访问</div></template>
